const original = $('Validate Input').first().json;
const videoDownload = $('Download Source Video').first().json;
const musicDownload = $('Download Soundtrack').first().json;

// Check if either download failed
if (videoDownload.error || videoDownload.detail) {
  return [{
    json: {
      error: true,
      message: 'Video download failed: ' + (videoDownload.detail || videoDownload.error || 'Unknown error')
    }
  }];
}

if (musicDownload.error || musicDownload.detail) {
  return [{
    json: {
      error: true,
      message: 'Music download failed: ' + (musicDownload.detail || musicDownload.error || 'Unknown error')
    }
  }];
}

// Safely extract downloaded public or local media URLs
const downloadedVideoUrl = videoDownload.mediaUrl || videoDownload.downloadUrl || original.videoUrl;
const downloadedMusicUrl = musicDownload.mediaUrl || musicDownload.downloadUrl || original.musicUrl;

return [{
  json: {
    videoUrl: downloadedVideoUrl,
    musicUrl: downloadedMusicUrl,
    text: original.text,
    title: original.title,
    durationSeconds: original.durationSeconds,
    width: original.width,
    height: original.height,
    style: original.style,
    fastApiBaseUrl: original.fastApiBaseUrl
  }
}];

